const demoDashboard: Dashboard = {
  totalPredictedDemand: 4910, highRiskRoutes: 1, averageRisk: .315, availableBuses: 29, totalRequiredCapacity: 5200, recommendedAdditionalBuses: 2,
  routes: demoRoutes, trend: ['06:00','08:00','10:00','12:00','14:00','16:00','18:00','20:00'].map((label, i) => ({ label, demand: [410,720,590,510,570,790,880,440][i], baseline: [390,650,620,530,540,710,770,420][i] })),
  riskDistribution: [{ name: 'Low', value: 2 }, { name: 'Medium', value: 1 }, { name: 'High', value: 1 }], activity: [{ title: 'Morning peak forecast refreshed', detail: 'A route capacity exceedance moved to 78%', time: '08 min ago' }, { title: 'Scenario saved', detail: 'Rainfall +15mm · Thursday 18:00', time: '42 min ago' }, { title: 'Model selection changed', detail: 'Gradient Boosting is now active', time: 'Yesterday' }],
};
const demoSummary: DataSummary = { datasetName: 'demo_2024_q2.csv', isDemo: true, records: 28416, routes: 4, stations: 16, missingValues: 38, invalidValues: 4, dateStart: '2024-04-01', dateEnd: '2024-06-30', averageDemand: 1228, maxDemand: 1934, quality: 'Good', columns: ['timestamp', 'route_id', 'station_id', 'demand', 'rainfall', 'temperature', 'is_holiday'] };
const demoAnalysis: Analysis = { correlations: [{ variable: 'hour', pearson: .71, spearman: .69, strength: 'Strong', interpretation: 'Demand rises consistently through commute windows.' }, { variable: 'temperature', pearson: .18, spearman: .22, strength: 'Weak', interpretation: 'Warm days have a modest positive association.' }, { variable: 'rainfall', pearson: -.34, spearman: -.31, strength: 'Moderate', interpretation: 'Rain shifts demand away from surface routes.' }, { variable: 'is_holiday', pearson: -.27, spearman: -.24, strength: 'Moderate', interpretation: 'Holiday schedules suppress commuter peaks.' }], regression: { equation: 'ŷ = 284.6 + 81.2h − 14.7r + 36.8t', r2: .74, coefficients: [{ variable: 'hour', coefficient: 81.2 }, { variable: 'rainfall', coefficient: -14.7 }, { variable: 'temperature', coefficient: 36.8 }] }, fourier: { dominantPeriod: 24, peakStrength: .81, pattern: 'Strong daily periodicity with a secondary weekly harmonic.', spectrum: [1, .42, .18, .12, .09, .07, .05, .04].map((amplitude, i) => ({ period: i + 1, amplitude })), actual: ['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map((label, i) => ({ label, demand: [1120,1240,1290,1260,1380,890,760][i], pattern: [1080,1210,1270,1290,1350,920,730][i] })) }, formulae: ['ŷ = β₀ + β₁x₁ + ε', 'P(demand > capacity) = 1 − Φ(z)'] };
const predictionFallback: PredictionResult = { routes: demoRoutes.map((r) => ({ routeId: r.routeId, predictedDemand: r.predictedDemand, historicalAverage: r.historicalAverage, difference: r.predictedDemand-r.historicalAverage, percentDifference: (r.predictedDemand/r.historicalAverage-1)*100, lowerBound: r.predictedDemand*.91, upperBound: r.predictedDemand*1.1 })), model: 'Gradient Boosting', metrics: { model: 'Gradient Boosting', mae: 84.6, rmse: 121.2, r2: .84, isBest: true }, conditions: 'Thursday 18:00 · dry · standard service day' };
function routePredictions(routes: RouteInsight[]): PredictionResult['routes'] {
  return routes.map((route) => ({
    routeId: route.routeId,
    predictedDemand: route.predictedDemand,
    historicalAverage: route.historicalAverage,
    difference: route.predictedDemand - route.historicalAverage,
    percentDifference: (route.predictedDemand / Math.max(1, route.historicalAverage) - 1) * 100,
    lowerBound: Math.max(0, route.predictedDemand * 0.9),
    upperBound: route.predictedDemand * 1.1,
  }));
}

function EmptyNotice({ text }: { text: string }) { return <div className="rounded-xl border border-dashed border-border p-8 text-center text-sm text-muted-foreground">{text}</div>; }
function ErrorNote({ retry }: { retry?: () => void }) { return <QueryState loading={false} error retry={retry} />; }
function MiniLine({ values, color = 'hsl(var(--primary))', fill = false }: { values: number[]; color?: string; fill?: boolean }) {
  const max = Math.max(...values), min = Math.min(...values);
  const points = values.map((v, i) => `${(i/(values.length-1))*100},${92-((v-min)/(max-min||1))*68}`).join(' ');
  return <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="h-full w-full overflow-visible"><line x1="0" y1="92" x2="100" y2="92" stroke="hsl(var(--border))" strokeWidth=".7" />{fill && <polygon points={`0,92 ${points} 100,92`} fill={color} opacity=".09" />}<polyline points={points} fill="none" stroke={color} strokeWidth="2.2" vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round" /></svg>;
}
function RiskBadge({ risk }: { risk: string }) { const high = risk.toLowerCase() === 'high', medium = risk.toLowerCase() === 'medium'; return <span className={`rounded-full px-2 py-1 font-mono-ui text-[9px] uppercase tracking-wider ${high ? 'bg-accent/12 text-accent' : medium ? 'bg-chart-4/15 text-chart-4' : 'bg-primary/12 text-primary'}`}>{risk}</span>; }
function RouteRows({ routes = demoRoutes }: { routes?: RouteInsight[] }) { return <div className="divide-y divide-border/70">{routes.map((r) => <div key={r.routeId} className="grid grid-cols-[1fr_auto] items-center gap-3 py-4 first:pt-0 last:pb-0 md:grid-cols-[1.4fr_1fr_.7fr_.7fr_auto]"><div className="flex min-w-0 items-center gap-3"><span className="h-8 w-1 rounded-full" style={{ background: r.color }} /><div className="min-w-0"><div className="font-display text-sm font-bold">{r.routeId} <span className="font-sans text-xs font-medium text-muted-foreground">· {r.name}</span></div><div className="mt-1 font-mono-ui text-[9px] uppercase tracking-wide text-muted-foreground">{r.stations.length} stations · {r.recommendedBuses} bus allocation</div></div></div><div className="hidden font-mono-ui text-xs md:block">{r.predictedDemand.toLocaleString()} <span className="text-muted-foreground">pax</span></div><div className="hidden font-mono-ui text-xs md:block">{Math.round(r.utilization*100)}%</div><div className="hidden md:block"><RiskBadge risk={r.risk} /></div><div className="text-right md:text-left"><RiskBadge risk={r.risk} /></div></div>)}</div>; }

export function OverviewPage() {
  const query = useGetDashboard();
  const dashboard = query.data ?? demoDashboard;
  return <><PageIntro eyebrow="Control room / 01" title="Good morning, Alex." description="A route-level read on the next service window. The model sees one constraint worth acting on." action={<Button onClick={() => query.refetch()} variant="outline" testId="button-refresh-dashboard"><RefreshCw size={14} /> Refresh signal</Button>} />
    {query.isError && <div className="mb-5"><ErrorNote retry={() => query.refetch()} /></div>}
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{<Stat label="Predicted demand" value={dashboard.totalPredictedDemand.toLocaleString()} detail="+8.4% against historical baseline" tone="good" />}<Stat label="High-risk routes" value={String(dashboard.highRiskRoutes).padStart(2,'0')} detail="A corridor needs an allocation decision" tone="alert" /><Stat label="Average risk" value={`${Math.round(dashboard.averageRisk*100)}%`} detail="Across active route windows" /><Stat label="Available fleet" value={String(dashboard.availableBuses)} detail={`${dashboard.recommendedAdditionalBuses} additional buses advised`} /></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><Panel title="Demand signal" meta="today · 06:00—20:00"><div className="flex items-end justify-between"><div><div className="font-display text-2xl font-bold">Peak shape is familiar</div><p className="mt-1 text-xs text-muted-foreground">The evening crest exceeds the baseline by 14.2%.</p></div><div className="flex items-center gap-3 font-mono-ui text-[9px] uppercase text-muted-foreground"><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-primary" /> forecast</span><span className="flex items-center gap-1.5"><i className="h-1.5 w-1.5 rounded-full bg-accent" /> baseline</span></div></div><div className="mt-7 h-48"><MiniLine values={dashboard.trend.map(x=>x.demand)} fill /><div className="mt-3 flex justify-between font-mono-ui text-[9px] text-muted-foreground">{dashboard.trend.map(x=><span key={x.label}>{x.label}</span>)}</div></div></Panel><Panel title="Risk distribution" meta="route windows"><div className="grid grid-cols-[1fr_150px] items-center gap-5"><div className="space-y-4">{dashboard.riskDistribution.map((x,i)=><div key={x.name}><div className="mb-1.5 flex justify-between text-xs"><span className="flex items-center gap-2"><i className={`h-2 w-2 rounded-full ${i===2?'bg-accent':i===1?'bg-chart-4':'bg-primary'}`} />{x.name}</span><span className="font-mono-ui">{x.value}</span></div><div className="h-1.5 overflow-hidden rounded-full bg-muted"><div className={`h-full rounded-full ${i===2?'bg-accent':i===1?'bg-chart-4':'bg-primary'}`} style={{ width: `${Math.max(15, x.value/4*100)}%` }} /></div></div>)}</div><div className="grid h-[150px] place-items-center rounded-full border-[18px] border-primary/25 relative"><div className="absolute inset-[-18px] rounded-full border-[18px] border-transparent border-t-accent border-r-accent rotate-[-25deg]" /><div className="text-center"><div className="font-display text-2xl font-bold">4</div><div className="font-mono-ui text-[8px] uppercase text-muted-foreground">routes</div></div></div></div></Panel></div>
    <div className="mt-5 grid gap-5 xl:grid-cols-[1.55fr_1fr]"><Panel title="Route watchlist" meta="sorted by probability"><RouteRows routes={dashboard.routes} /></Panel><Panel title="Recent analysis" meta="activity log"><div className="space-y-5">{dashboard.activity.map((a,i)=><div key={a.title} className="flex gap-3"><div className={`mt-1.5 h-2 w-2 shrink-0 rounded-full ${i===0?'bg-accent':'bg-primary'}`} /><div><div className="text-xs font-bold">{a.title}</div><div className="mt-1 text-[11px] leading-5 text-muted-foreground">{a.detail}</div><div className="mt-1 font-mono-ui text-[9px] uppercase text-muted-foreground/70">{a.time}</div></div></div>)}</div></Panel></div>
  </>;
}

export function DataPage() {
  const summaryQuery = useGetDataSummary();
  const loadDemo = useLoadDemoDataset();
  const upload = useUploadDataset();
  const [fileName, setFileName] = useState('');
  const summary = (loadDemo.data ?? upload.data ?? summaryQuery.data ?? demoSummary) as DataSummary;
  const handleFile = (file?: File) => { if (!file) return; setFileName(file.name); const reader = new FileReader(); reader.onload = () => upload.mutate({ data: String(reader.result ?? '') }); reader.readAsText(file); };
  return <><PageIntro eyebrow="Data intake / 02" title="Give the signal a clean surface." description="Load a timetable-shaped CSV, inspect its provenance, and keep the assumptions visible before analysis begins." action={<Button onClick={() => loadDemo.mutate()} disabled={loadDemo.isPending} testId="button-load-demo">{loadDemo.isPending ? <LoaderCircle size={14} className="animate-spin" /> : <FlaskConical size={14} />} Load demo data</Button>} />
    <div className="grid gap-5 xl:grid-cols-[1.1fr_1fr]"><Panel title="Dataset intake" meta="CSV / UTF-8"><label htmlFor="csv-upload" className="grid min-h-[235px] cursor-pointer place-items-center rounded-xl border border-dashed border-primary/35 bg-primary/[.035] p-8 text-center transition-colors hover:bg-primary/[.07]"><input id="csv-upload" type="file" accept=".csv,text/csv" className="sr-only" onChange={e=>handleFile(e.target.files?.[0])} data-testid="input-csv-upload" /><div><div className="mx-auto grid h-12 w-12 place-items-center rounded-xl bg-primary/10 text-primary"><CloudUpload size={23} /></div><div className="mt-4 font-display font-bold">{fileName || 'Drop a CSV here, or browse'}</div><p className="mt-1 text-xs text-muted-foreground">Required fields: timestamp, route_id, station_id, demand</p><div className="mt-5 inline-flex items-center gap-2 rounded-lg border border-border bg-card px-3 py-2 text-[11px] font-bold"><Upload size={13} /> Choose file</div></div></label>{upload.isError && <div className="mt-3 text-xs text-accent" data-testid="status-upload-error">Upload rejected. Check the column contract and try again.</div>}{upload.isSuccess && <div className="mt-3 text-xs font-semibold text-primary" data-testid="status-upload-success">Dataset accepted and made active.</div>}</Panel><Panel title="Quality gate" meta={summary.quality}><div className="flex items-start justify-between"><div><div className="font-display text-3xl font-bold">{summary.quality}</div><div className="mt-1 font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{summary.datasetName}</div></div><div className="rounded-full border border-primary/30 bg-primary/10 px-3 py-1.5 font-mono-ui text-[9px] uppercase text-primary">validated</div></div><div className="mt-7 grid grid-cols-2 gap-x-5 gap-y-5 sm:grid-cols-4 xl:grid-cols-2">{[['Records',summary.records.toLocaleString()],['Routes',summary.routes],['Stations',summary.stations],['Missing',summary.missingValues],['Invalid',summary.invalidValues],['Average demand',summary.averageDemand.toLocaleString()],['Max demand',summary.maxDemand.toLocaleString()],['Window',`${summary.dateStart.slice(5)} → ${summary.dateEnd.slice(5)}`]].map(([l,v])=><div key={String(l)}><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-1 text-sm font-bold">{v}</div></div>)}</div></Panel></div><div className="mt-5"><Panel title="Column contract" meta={`${summary.columns.length} observed fields`}><div className="flex flex-wrap gap-2">{summary.columns.map((column,i)=><span key={column} className={`rounded-md border px-3 py-2 font-mono-ui text-[10px] ${i<4?'border-primary/30 bg-primary/[.06] text-primary':'border-border text-muted-foreground'}`}>{column}{i<4&&<Check size={11} className="ml-2 inline" />}</span>)}</div><div className="mt-5 flex items-center gap-2 border-t border-border/70 pt-4 text-[11px] text-muted-foreground"><Info size={14} className="text-primary" /> Demo data is deterministic: useful for a viva, not a substitute for your AVL feed.</div></Panel></div>
  </>;
}

export function AnalysisPage() {
  const query = useGetAnalysis(); const analysis = query.data ?? demoAnalysis;
  return <><PageIntro eyebrow="Analysis / 03" title="Show your working." description="Correlation is not causation. These panels keep the evidence, fit, and periodic structure separate enough to interrogate." action={<Button onClick={() => query.refetch()} variant="outline" testId="button-refresh-analysis"><RefreshCw size={14} /> Recompute</Button>} />{query.isError&&<div className="mb-5"><ErrorNote retry={()=>query.refetch()} /></div>}<div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Association matrix" meta="Pearson / Spearman"><div className="overflow-x-auto"><table className="w-full min-w-[560px] text-left text-xs"><thead><tr className="border-b border-border text-[9px] uppercase tracking-[.15em] text-muted-foreground"><th className="pb-3">Variable</th><th className="pb-3">Pearson r</th><th className="pb-3">Spearman ρ</th><th className="pb-3">Read</th></tr></thead><tbody>{analysis.correlations.map((c)=><tr key={c.variable} className="border-b border-border/60 last:border-0"><td className="py-4 font-bold">{c.variable}</td><td className="py-4 font-mono-ui">{c.pearson.toFixed(2)}</td><td className="py-4 font-mono-ui">{c.spearman.toFixed(2)}</td><td className="py-4"><div className="flex items-center gap-2"><span className="h-1.5 w-16 overflow-hidden rounded-full bg-muted"><span className="block h-full rounded-full bg-primary" style={{ width: `${Math.abs(c.pearson)*100}%` }} /></span><span className="text-muted-foreground">{c.strength}</span></div></td></tr>)}</tbody></table></div><div className="mt-4 border-t border-border/70 pt-4 text-[11px] leading-5 text-muted-foreground">Pearson sees linear association; Spearman preserves rank. Their agreement is a useful stability check, not a causal claim.</div></Panel><Panel title="Regression evidence" meta="ordinary least squares"><div className="rounded-xl bg-sidebar p-5 text-sidebar-foreground"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-sidebar-foreground/45">fitted equation</div><div className="mt-4 break-words font-mono-ui text-sm leading-7 text-sidebar-primary">{analysis.regression.equation}</div><div className="mt-5 flex items-end justify-between border-t border-sidebar-border pt-4"><span className="font-mono-ui text-[10px] uppercase text-sidebar-foreground/50">R² goodness of fit</span><span className="font-display text-3xl font-bold">{analysis.regression.r2.toFixed(2)}</span></div></div><div className="mt-5 space-y-3">{analysis.regression.coefficients.map(c=><div key={c.variable} className="flex items-center justify-between text-xs"><span className="text-muted-foreground">{c.variable}</span><span className={`font-mono-ui ${c.coefficient<0?'text-accent':'text-primary'}`}>{c.coefficient>0?'+':''}{c.coefficient.toFixed(1)}</span></div>)}</div></Panel></div><div className="mt-5 grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Panel title="Fourier pattern" meta="discrete spectrum"><div className="grid gap-6 sm:grid-cols-[.8fr_1.2fr]"><div><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">dominant period</div><div className="mt-2 font-display text-5xl font-bold">{analysis.fourier.dominantPeriod}<span className="ml-1 text-base font-sans font-medium text-muted-foreground">hours</span></div><div className="mt-4 flex items-center gap-2 text-xs"><Waypoints size={14} className="text-primary" /> peak strength <span className="font-mono-ui text-primary">{analysis.fourier.peakStrength.toFixed(2)}</span></div><p className="mt-5 text-xs leading-5 text-muted-foreground">{analysis.fourier.pattern}</p></div><div className="flex h-40 items-end gap-2 border-b border-border px-2">{analysis.fourier.spectrum.map((v,i)=><div key={i} className="group flex flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-sm bg-primary/70 transition-all group-hover:bg-primary" style={{ height: `${Math.max(v.amplitude*100,4)}%` }} /><span className="font-mono-ui text-[8px] text-muted-foreground">{v.period}</span></div>)}</div></div></Panel><Panel title="Actual vs periodic component" meta="weekly aggregation"><div className="h-48"><MiniLine values={analysis.fourier.actual.map(x=>x.demand)} fill /><div className="mt-3 flex justify-between font-mono-ui text-[9px] text-muted-foreground">{analysis.fourier.actual.map(x=><span key={x.label}>{x.label}</span>)}</div></div></Panel></div></>;
}

function ConditionField({ label, value, onChange, min, max, step='1', suffix }: { label:string; value:string|number; onChange:(v:string)=>void; min?:string; max?:string; step?:string; suffix?:string }) { return <label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{label}</span><div className="mt-2 flex items-center rounded-lg border border-input bg-background"><input type="number" min={min} max={max} step={step} value={value} onChange={e=>onChange(e.target.value)} data-testid={`input-${label.toLowerCase().replaceAll(' ','-')}`} className="w-full bg-transparent px-3 py-2.5 text-sm font-semibold outline-none" />{suffix&&<span className="pr-3 font-mono-ui text-[10px] text-muted-foreground">{suffix}</span>}</div></label>; }

export function PredictionPage() {
  const modelsQuery = useCompareModels(); const predict = usePredictDemand(); const [date,setDate]=useState('2024-06-27'); const [hour,setHour]=useState('18'); const [rainfall,setRainfall]=useState('0'); const [temperature,setTemperature]=useState('19'); const [multiplier,setMultiplier]=useState('1'); const [holiday,setHoliday]=useState(false); const [event,setEvent]=useState(false); const [result,setResult]=useState<PredictionResult|null>(null); const models=modelsQuery.data?.metrics ?? [{ model:'Gradient Boosting',mae:84.6,rmse:121.2,r2:.84,isBest:true }];
  const run=()=>predict.mutate({data:{date,hour:Number(hour),rainfall:Number(rainfall),temperature:Number(temperature),demandMultiplier:Number(multiplier),isHoliday:holiday,specialEvent:event,model:modelsQuery.data?.selectedModel}}, {onSuccess:setResult});
  const shown=result ?? predictionFallback;
  return <><PageIntro eyebrow="Prediction / 04" title="Ask the next hour a better question." description="Adjust the exogenous conditions, then read the route-level forecast with its uncertainty interval intact." action={<Button onClick={run} disabled={predict.isPending} testId="button-run-prediction">{predict.isPending?<LoaderCircle size={14} className="animate-spin"/>:<Play size={14}/>} Run forecast</Button>} /><div className="grid gap-5 xl:grid-cols-[310px_1fr]"><Panel title="Scenario controls" meta="input vector"><div className="space-y-4"><label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">date</span><input type="date" value={date} onChange={e=>setDate(e.target.value)} data-testid="input-date" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm font-semibold outline-none" /></label><ConditionField label="hour" value={hour} onChange={setHour} min="0" max="23" suffix="h" /><ConditionField label="rainfall" value={rainfall} onChange={setRainfall} min="0" step=".1" suffix="mm" /><ConditionField label="temperature" value={temperature} onChange={setTemperature} step=".1" suffix="°C" /><ConditionField label="demand multiplier" value={multiplier} onChange={setMultiplier} min=".1" max="3" step=".05" /><div className="space-y-3 border-t border-border/70 pt-4"><label className="flex items-center justify-between text-xs font-semibold">Public holiday <input type="checkbox" checked={holiday} onChange={e=>setHoliday(e.target.checked)} data-testid="input-holiday" className="h-4 w-4 accent-[hsl(var(--primary))]" /></label><label className="flex items-center justify-between text-xs font-semibold">Special event <input type="checkbox" checked={event} onChange={e=>setEvent(e.target.checked)} data-testid="input-special-event" className="h-4 w-4 accent-[hsl(var(--primary))]" /></label></div></div></Panel><div className="space-y-5"><Panel title="Route forecast" meta={`${shown.model} · ${shown.conditions}`}><div className="space-y-5">{shown.routes.map((r,i)=><div key={r.routeId} className="grid gap-3 border-b border-border/60 pb-5 last:border-0 last:pb-0 md:grid-cols-[100px_1fr_120px] md:items-center"><div><div className="font-display text-lg font-bold">{r.routeId}</div><div className="font-mono-ui text-[9px] uppercase text-muted-foreground">route signal</div></div><div><div className="flex items-center justify-between text-xs"><span>forecast <strong className="font-mono-ui">{Math.round(r.predictedDemand).toLocaleString()}</strong></span><span className="font-mono-ui text-muted-foreground">{Math.round(r.lowerBound)} — {Math.round(r.upperBound)}</span></div><div className="relative mt-3 h-2 rounded-full bg-muted"><div className="absolute h-2 rounded-full bg-primary/25" style={{left:`${Math.max(0, r.lowerBound/r.upperBound*65)}%`,right:'10%'}}/><div className="absolute top-[-3px] h-4 w-1 rounded-full bg-primary" style={{left:`${Math.min(92, r.predictedDemand/r.upperBound*80)}%`}}/></div></div><div className={`text-right font-mono-ui text-xs ${r.percentDifference>0?'text-primary':'text-accent'}`}>{r.percentDifference>0?'+':''}{r.percentDifference.toFixed(1)}%</div></div>)}</div></Panel>{predict.isError&&<ErrorNote/>}<Panel title="Model evidence" meta="holdout metrics"><div className="grid gap-3 sm:grid-cols-3">{models.map((m)=><div key={m.model} className={`rounded-xl border p-4 ${m.isBest?'border-primary/40 bg-primary/[.05]':'border-border'}`}><div className="flex items-center justify-between"><span className="font-display text-xs font-bold">{m.model}</span>{m.isBest&&<span className="font-mono-ui text-[8px] uppercase text-primary">active</span>}</div><div className="mt-4 grid grid-cols-3 gap-2 font-mono-ui text-[10px]"><span>MAE<br/><b className="text-foreground">{m.mae.toFixed(1)}</b></span><span>RMSE<br/><b className="text-foreground">{m.rmse.toFixed(1)}</b></span><span>R²<br/><b className="text-foreground">{m.r2.toFixed(2)}</b></span></div></div>)}</div></Panel></div></div></>;
}

function predictionsFromRoutes(routes: RouteInsight[]): PredictionRoute[] {
  return routes.map((route) => ({
    routeId: route.routeId,
    predictedDemand: route.predictedDemand,
    historicalAverage: route.historicalAverage,
    difference: route.predictedDemand - route.historicalAverage,
    percentDifference: route.historicalAverage ? ((route.predictedDemand / route.historicalAverage) - 1) * 100 : 0,
    lowerBound: route.predictedDemand * .91,
    upperBound: route.predictedDemand * 1.1,
  }));
}
export function RiskPage() {
  const dashboardQuery = useGetDashboard();
  const dashboard = dashboardQuery.data ?? demoDashboard;
  const risk=useCalculateRisk(); const [buses,setBuses]=useState('29'); const [capacity,setCapacity]=useState('240'); const [result,setResult]=useState<RiskResult|null>(null); const run=()=>risk.mutate({data:{predictions:predictionsFromRoutes(dashboard.routes),availableBuses:Number(buses),busCapacity:Number(capacity)}},{onSuccess:setResult}); const rows=result?.routes ?? dashboard.routes.map(r=>({routeId:r.routeId,predictedDemand:r.predictedDemand,capacity:r.capacity,utilization:r.utilization,probability:r.overcrowdingProbability,risk:r.risk})); const priorityRoute=dashboard.routes.slice().sort((a,b)=>b.overcrowdingProbability-a.overcrowdingProbability)[0]; return <><PageIntro eyebrow="Risk / 05" title="Put a probability on the pinch point." description="Residual uncertainty becomes operational risk only after capacity and fleet assumptions are made explicit." action={<Button onClick={run} disabled={risk.isPending} testId="button-calculate-risk">{risk.isPending?<LoaderCircle size={14} className="animate-spin"/>:<Sigma size={14}/>} Calculate risk</Button>} />{dashboardQuery.isError&&<div className="mb-5"><ErrorNote retry={()=>dashboardQuery.refetch()}/></div>}<div className="grid gap-5 xl:grid-cols-[310px_1fr]"><Panel title="Assumptions" meta="scenario inputs"><div className="space-y-4"><ConditionField label="available buses" value={buses} onChange={setBuses} min="1" /><ConditionField label="bus capacity" value={capacity} onChange={setCapacity} min="1" /><div className="rounded-xl bg-muted/70 p-4 text-[11px] leading-5 text-muted-foreground"><Info size={14} className="mb-2 text-primary" />Probability estimates the share of residual draws where predicted demand exceeds assigned capacity. It is not a service-level guarantee.</div></div></Panel><div className="space-y-5"><Panel title="Exceedance probability" meta="route × capacity"><div className="overflow-x-auto"><table className="w-full min-w-[600px] text-left text-xs"><thead><tr className="border-b border-border text-[9px] uppercase tracking-wider text-muted-foreground"><th className="pb-3">Route</th><th className="pb-3">Demand</th><th className="pb-3">Capacity</th><th className="pb-3">Utilization</th><th className="pb-3">Probability</th><th className="pb-3">Risk</th></tr></thead><tbody>{rows.map(r=><tr key={r.routeId} className="border-b border-border/60 last:border-0"><td className="py-4 font-display font-bold">{r.routeId}</td><td className="py-4 font-mono-ui">{Math.round(r.predictedDemand)}</td><td className="py-4 font-mono-ui">{Math.round(r.capacity)}</td><td className="py-4 font-mono-ui">{Math.round(r.utilization*100)}%</td><td className="py-4"><div className="flex items-center gap-2"><span className="h-1.5 w-16 rounded-full bg-muted"><span className="block h-full rounded-full bg-accent" style={{width:`${Math.max(3,r.probability*100)}%`}}/></span><span className="font-mono-ui">{Math.round(r.probability*100)}%</span></div></td><td className="py-4"><RiskBadge risk={r.risk}/></td></tr>)}</tbody></table></div></Panel>{risk.isError&&<ErrorNote/>}<Panel title="Interpretation" meta="model note"><div className="flex gap-4"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-accent/10 text-accent"><CircleAlert size={18}/></div><div><div className="font-display font-bold">One route dominates the tail risk.</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{result?.assumption ?? `${priorityRoute?.routeId ?? 'The priority route'} has a ${Math.round((priorityRoute?.overcrowdingProbability ?? 0)*100)}% estimated exceedance probability under current fleet capacity. Additional allocation is the most direct mitigation.`}</p></div></div></Panel></div></div></>;
}

export function OptimizationPage() {
  const dashboardQuery = useGetDashboard();
  const dashboard = dashboardQuery.data ?? demoDashboard;
  const solve=useSolveOptimization(); const [buses,setBuses]=useState('29'); const [capacity,setCapacity]=useState('240'); const [min,setMin]=useState('2'); const [max,setMax]=useState('12'); const [result,setResult]=useState<OptimizationResult|null>(null); const run=()=>solve.mutate({data:{predictions:predictionsFromRoutes(dashboard.routes),availableBuses:Number(buses),busCapacity:Number(capacity),minBusesPerRoute:Number(min),maxBusesPerRoute:Number(max)}},{onSuccess:setResult}); const rows=result?.routes ?? dashboard.routes.map(r=>({routeId:r.routeId,buses:r.recommendedBuses,capacity:r.recommendedBuses*240,predictedDemand:r.predictedDemand,utilization:r.utilization,overcrowding:Math.max(0,r.predictedDemand-r.recommendedBuses*240),unusedCapacity:Math.max(0,r.recommendedBuses*240-r.predictedDemand)})); const priorityRoute=dashboard.routes.slice().sort((a,b)=>b.overcrowdingProbability-a.overcrowdingProbability)[0]; return <><PageIntro eyebrow="Optimization / 06" title="Make the constraint legible." description="The recommended fleet is a solution, not a guess: minimize uncovered demand while respecting a finite bus pool." action={<Button onClick={run} disabled={solve.isPending} testId="button-solve-optimization">{solve.isPending?<LoaderCircle size={14} className="animate-spin"/>:<TargetIcon/>} Solve allocation</Button>} />{dashboardQuery.isError&&<div className="mb-5"><ErrorNote retry={()=>dashboardQuery.refetch()}/></div>}<div className="grid gap-5 xl:grid-cols-[310px_1fr]"><Panel title="Constraint set" meta="integer program"><div className="space-y-4"><ConditionField label="available buses" value={buses} onChange={setBuses} min="1"/><ConditionField label="bus capacity" value={capacity} onChange={setCapacity} min="1"/><ConditionField label="min / route" value={min} onChange={setMin} min="0"/><ConditionField label="max / route" value={max} onChange={setMax} min="1"/><div className="rounded-xl border border-primary/25 bg-primary/[.05] p-4 font-mono-ui text-[10px] leading-5 text-muted-foreground">minimize Σ overcrowdingᵢ + 0.05 × unused_capacityᵢ<br/>subject to Σ busesᵢ ≤ {buses}<br/>and {min} ≤ busesᵢ ≤ {max}</div></div></Panel><div className="space-y-5"><Panel title="Allocation result" meta="before → after"><div className="mb-5 grid gap-3 sm:grid-cols-3"><Stat label="Objective" value={(result?.objectiveValue??38.4).toFixed(1)} detail="lower is better" tone="good"/><Stat label="Total buses" value={String(result?.totalBuses??25)} detail={`${buses} available`} /><Stat label="Capacity covered" value={`${Math.round((result?.totalCapacity??6000)/(result?.totalDemand??4910)*100)}%`} detail="of predicted demand" tone="good"/></div><div className="overflow-x-auto"><table className="w-full min-w-[620px] text-left text-xs"><thead><tr className="border-b border-border text-[9px] uppercase tracking-wider text-muted-foreground"><th className="pb-3">Route</th><th className="pb-3">Buses</th><th className="pb-3">Capacity</th><th className="pb-3">Demand</th><th className="pb-3">Utilization</th><th className="pb-3">Unused</th></tr></thead><tbody>{rows.map(r=><tr key={r.routeId} className="border-b border-border/60 last:border-0"><td className="py-4 font-display font-bold">{r.routeId}</td><td className="py-4 font-mono-ui text-primary">{r.buses}</td><td className="py-4 font-mono-ui">{r.capacity}</td><td className="py-4 font-mono-ui">{Math.round(r.predictedDemand)}</td><td className="py-4 font-mono-ui">{Math.round(r.utilization*100)}%</td><td className="py-4 font-mono-ui text-muted-foreground">{Math.round(r.unusedCapacity)}</td></tr>)}</tbody></table></div></Panel>{solve.isError&&<ErrorNote/>}<Panel title="Solver formulation" meta="why this recommendation"><p className="text-xs leading-6 text-muted-foreground">{result?.formulation ?? `An integer allocation balances residual overcrowding against unused capacity. It prioritizes ${priorityRoute?.routeId ?? 'the highest-risk route'} because its marginal bus removes the most exceedance probability from the network.`}</p></Panel></div></div></>; }
function TargetIcon(){return <span className="grid place-items-center"><Target size={14}/></span>}

export function SimulatorPage() {
  const models=useCompareModels(); const simulation=useRunSimulation(); const [rainfall,setRainfall]=useState('12'); const [temperature,setTemperature]=useState('16'); const [multiplier,setMultiplier]=useState('1.15'); const [buses,setBuses]=useState('29'); const [unavailable,setUnavailable]=useState(''); const [result,setResult]=useState<SimulationResult|null>(null); const run=()=>simulation.mutate({data:{availableBuses:Number(buses),rainfall:Number(rainfall),temperature:Number(temperature),demandMultiplier:Number(multiplier),isHoliday:false,specialEvent:true,unavailableRoute:unavailable||undefined,model:models.data?.selectedModel}},{onSuccess:setResult}); const out=result ?? {baseline:{demand:4910,risk:.315,buses:25,objectiveValue:38.4},scenario:{demand:5524,risk:.42,buses:29,objectiveValue:51.2},routes:demoRoutes,label:'Thursday event + rainfall'}; return <><PageIntro eyebrow="Simulator / 07" title="Stress the network before it stresses you." description="Change one or two conditions, then compare the same decision pipeline against its baseline." action={<Button onClick={run} disabled={simulation.isPending} testId="button-run-simulation">{simulation.isPending?<LoaderCircle size={14} className="animate-spin"/>:<Play size={14}/>} Run scenario</Button>} /><div className="grid gap-5 xl:grid-cols-[310px_1fr]"><Panel title="What-if conditions" meta="scenario vector"><div className="space-y-4"><ConditionField label="rainfall" value={rainfall} onChange={setRainfall} min="0" step=".1" suffix="mm"/><ConditionField label="temperature" value={temperature} onChange={setTemperature} step=".1" suffix="°C"/><ConditionField label="demand multiplier" value={multiplier} onChange={setMultiplier} min=".1" max="3" step=".05"/><ConditionField label="available buses" value={buses} onChange={setBuses} min="1"/><label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">unavailable route</span><select value={unavailable} onChange={e=>setUnavailable(e.target.value)} data-testid="select-unavailable-route" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm font-semibold outline-none"><option value="">none</option>{demoRoutes.map(r=><option key={r.routeId} value={r.routeId}>{r.routeId} · {r.name}</option>)}</select></label></div></Panel><div className="space-y-5"><Panel title={out.label} meta="baseline versus scenario"><div className="grid gap-4 sm:grid-cols-3">{[['Demand',out.baseline.demand,out.scenario.demand],['Risk',out.baseline.risk*100,out.scenario.risk*100],['Objective',out.baseline.objectiveValue,out.scenario.objectiveValue]].map(([label,b,s])=><div key={String(label)} className="rounded-xl border border-border p-4"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{label}</div><div className="mt-3 flex items-end justify-between"><span className="font-display text-2xl font-bold">{label==='Risk'?`${Number(s).toFixed(0)}%`:Math.round(Number(s)).toLocaleString()}</span><span className="flex items-center gap-1 text-[10px] text-accent"><ArrowUpRight size={12}/>{Math.round((Number(s)/Number(b)-1)*100)}%</span></div><div className="mt-3 flex gap-1"><div className="h-1.5 flex-1 rounded-full bg-muted"><div className="h-full rounded-full bg-muted-foreground/35" style={{width:`${Math.min(100,Number(b)/(Number(s)||1)*100)}%`}}/></div><div className="h-1.5 flex-1 rounded-full bg-accent/20"><div className="h-full rounded-full bg-accent" style={{width:'100%'}}/></div></div><div className="mt-2 flex justify-between font-mono-ui text-[8px] text-muted-foreground"><span>base {label==='Risk'?`${Number(b).toFixed(0)}%`:Math.round(Number(b))}</span><span>scenario</span></div></div>)}</div></Panel><Panel title="Route response" meta="scenario output"><RouteRows routes={out.routes}/></Panel>{simulation.isError&&<ErrorNote/>}</div></div></>;
}

export function ModelsPage(){ const q=useCompareModels(); const metrics=q.data?.metrics ?? [{model:'Gradient Boosting',mae:84.6,rmse:121.2,r2:.84,isBest:true},{model:'Random Forest',mae:96.3,rmse:145.8,r2:.76,isBest:false},{model:'Seasonal Naive',mae:122.5,rmse:181.3,r2:.61,isBest:false}]; return <><PageIntro eyebrow="Models / 08" title="Know what you are trusting." description="The selected model is only as good as its holdout. Compare error, fit, and the methodology behind the score." action={<Button onClick={()=>q.refetch()} variant="outline" testId="button-refresh-models"><RefreshCw size={14}/> Re-run holdout</Button>}/><div className="grid gap-5 xl:grid-cols-[1fr_340px]"><Panel title="Model comparison" meta="time-ordered holdout"><div className="space-y-3">{metrics.map((m)=><div key={m.model} className={`grid gap-3 rounded-xl border p-5 sm:grid-cols-[1.3fr_1fr_1fr_1fr] sm:items-center ${m.isBest?'border-primary/40 bg-primary/[.045]':'border-border'}`}><div className="flex items-center gap-3"><div className={`grid h-8 w-8 place-items-center rounded-lg ${m.isBest?'bg-primary text-primary-foreground':'bg-muted text-muted-foreground'}`}>{m.isBest ? <Check size={16}/> : <BarChart3 size={15}/>}</div><div><div className="font-display text-sm font-bold">{m.model}</div>{m.isBest&&<div className="mt-1 font-mono-ui text-[9px] uppercase tracking-wider text-primary">selected for production</div>}</div></div><div><div className="font-mono-ui text-[9px] text-muted-foreground">MAE</div><div className="mt-1 font-mono-ui text-sm">{m.mae.toFixed(1)}</div></div><div><div className="font-mono-ui text-[9px] text-muted-foreground">RMSE</div><div className="mt-1 font-mono-ui text-sm">{m.rmse.toFixed(1)}</div></div><div><div className="font-mono-ui text-[9px] text-muted-foreground">R²</div><div className="mt-1 font-mono-ui text-sm">{m.r2.toFixed(2)}</div></div></div>)}</div></Panel><Panel title="Selected model" meta="current"><div className="rounded-xl bg-sidebar p-5 text-sidebar-foreground"><div className="font-mono-ui text-[9px] uppercase tracking-[.17em] text-sidebar-foreground/45">production forecast</div><div className="mt-3 font-display text-2xl font-bold text-sidebar-primary">{q.data?.selectedModel ?? 'Gradient Boosting'}</div><p className="mt-4 text-xs leading-5 text-sidebar-foreground/65">{q.data?.methodology ?? 'Time-ordered 80/20 holdout. Features are standardized before fitting. Report uncertainty separately from point accuracy.'}</p></div><div className="mt-5 flex items-start gap-3 text-xs leading-5 text-muted-foreground"><Info size={15} className="mt-0.5 shrink-0 text-primary"/> Lower MAE is preferable for typical error; RMSE makes rare misses visible.</div></Panel></div></>; }

export function RoutesPage(){ const q=useGetRoutes(); const routes=q.data ?? demoRoutes; const [selected,setSelected]=useState('M1'); const active=routes.find(r=>r.routeId===selected)??routes[0]; return <><PageIntro eyebrow="Routes / 09" title="Read the network as a system." description="A demonstration network map pairs spatial intuition with the route-level metrics that actually drive allocation." action={<Button onClick={()=>q.refetch()} variant="outline" testId="button-refresh-routes"><RefreshCw size={14}/> Refresh routes</Button>}/><div className="grid gap-5 xl:grid-cols-[1.3fr_.7fr]"><Panel title="Demonstration transport network" meta="schematic coordinates"><div className="grid-paper relative min-h-[470px] overflow-hidden rounded-xl border border-border/70 bg-background/55 p-4"><div className="absolute inset-x-7 top-1/2 border-t border-dashed border-border/80"/><div className="absolute inset-y-7 left-1/2 border-l border-dashed border-border/80"/><div className="absolute left-5 top-5 font-mono-ui text-[9px] uppercase tracking-widest text-muted-foreground">north / service geography</div>{routes.map(r=><button type="button" key={r.routeId} onClick={()=>setSelected(r.routeId)} data-testid={`button-map-route-${r.routeId}`} className={`absolute inset-0 h-full w-full transition-opacity ${selected===r.routeId?'opacity-100':'opacity-45 hover:opacity-75'}`}><svg className="h-full w-full" viewBox="0 0 100 100" preserveAspectRatio="none"><polyline points={r.coordinates.map((_,i)=>`${15+(i/(Math.max(1,r.coordinates.length-1)))*70},${24+((i*17+Number(r.routeId.slice(1))*9)%53)}`).join(' ')} fill="none" stroke={r.color} strokeWidth={selected===r.routeId?1.5:.9} vectorEffect="non-scaling-stroke" strokeLinecap="round" strokeLinejoin="round"/>{r.coordinates.map((_,i)=><circle key={i} cx={15+(i/(Math.max(1,r.coordinates.length-1)))*70} cy={24+((i*17+Number(r.routeId.slice(1))*9)%53)} r={selected===r.routeId?1.8:1.2} fill="hsl(var(--card))" stroke={r.color} strokeWidth=".8" vectorEffect="non-scaling-stroke"/>)}</svg></button>)}<div className="absolute bottom-4 left-4 flex flex-wrap gap-3 rounded-lg border border-border bg-card/90 px-3 py-2 backdrop-blur-sm">{routes.map(r=><button type="button" key={r.routeId} onClick={()=>setSelected(r.routeId)} data-testid={`button-legend-route-${r.routeId}`} className="flex items-center gap-1.5 font-mono-ui text-[9px]"><i className="h-2 w-2 rounded-full" style={{background:r.color}}/>{r.routeId}</button>)}</div></div></Panel><Panel title={`${active?.routeId ?? '—'} intelligence`} meta="selected route">{active?<><div className="flex items-center gap-3"><span className="h-10 w-1 rounded-full" style={{background:active.color}}/><div><div className="font-display text-xl font-bold">{active.name}</div><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{active.stations.length} stations · {active.recommendedBuses} recommended buses</div></div></div><div className="mt-7 grid grid-cols-2 gap-5">{[['Forecast',active.predictedDemand.toLocaleString()],['Capacity',active.capacity.toLocaleString()],['Utilization',`${Math.round(active.utilization*100)}%`],['Risk',`${Math.round(active.overcrowdingProbability*100)}%`]].map(([l,v])=><div key={l}><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">{l}</div><div className="mt-1 font-display text-2xl font-bold">{v}</div></div>)}</div><div className="mt-7 border-t border-border/70 pt-5"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">station sequence</div><div className="mt-3 space-y-3">{active.stations.map((s,i)=><div key={s} className="flex items-center gap-3 text-xs"><span className="grid h-5 w-5 place-items-center rounded-full border border-border font-mono-ui text-[8px]">{i+1}</span>{s}</div>)}</div></div></>:<EmptyNotice text="No route selected."/>}</Panel></div></>; }

export function InsightsPage(){ const analysis=useGetAnalysis(); const dashboardQuery=useGetDashboard(); const explain=useExplainResults(); const a=analysis.data??demoAnalysis; const routes=dashboardQuery.data?.routes??demoDashboard.routes; const priorityRoute=routes.slice().sort((x,y)=>y.overcrowdingProbability-x.overcrowdingProbability)[0]; const [configured,setConfigured]=useState(false); const run=()=>explain.mutate({data:{topic:`${priorityRoute?.routeId??'priority route'} capacity risk`,evidence:`Predicted demand is ${priorityRoute?.predictedDemand??0}; capacity is ${priorityRoute?.capacity??0}; exceedance probability is ${Math.round((priorityRoute?.overcrowdingProbability??0)*100)}%.`}}, {onSuccess:()=>setConfigured(true)}); return <><PageIntro eyebrow="Insights / 10" title="Separate evidence from narration." description="Mathematical evidence is always present. An optional explanation can make the result easier to communicate in a review." action={<Button onClick={run} disabled={explain.isPending} testId="button-explain-results">{explain.isPending?<LoaderCircle size={14} className="animate-spin"/>:<Sparkles size={14}/>} Explain with AI</Button>}/>{dashboardQuery.isError&&<div className="mb-5"><ErrorNote retry={()=>dashboardQuery.refetch()}/></div>}<div className="grid gap-5 xl:grid-cols-[1.1fr_.9fr]"><Panel title="Mathematical evidence" meta="always on"><div className="space-y-4">{[{label:'Association',text:`Hour has the strongest linear association with demand (Pearson r = ${a.correlations[0]?.pearson.toFixed(2)}).`},{label:'Fit',text:`The regression explains ${(a.regression.r2*100).toFixed(0)}% of observed variance in the holdout window.`},{label:'Periodicity',text:`The Fourier spectrum peaks at a ${a.fourier.dominantPeriod}-hour period with strength ${a.fourier.peakStrength.toFixed(2)}.`},{label:'Decision',text:`${priorityRoute?.routeId??'The priority route'} has the highest live exceedance probability at ${Math.round((priorityRoute?.overcrowdingProbability??0)*100)}% under the active service window.`}].map((x,i)=><div key={x.label} className="flex gap-4 rounded-xl border border-border/70 p-4"><div className="font-mono-ui text-[10px] text-primary">0{i+1}</div><div><div className="font-display text-sm font-bold">{x.label}</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{x.text}</p></div></div>)}</div></Panel><Panel title="Optional explanation" meta={configured||explain.data?.configured?'configured':'not configured'}><div className={`min-h-[280px] rounded-xl p-5 ${configured||explain.data?.configured?'bg-primary/[.06]':'bg-muted/60'}`}>{configured||explain.data?.configured?<><div className="flex items-center gap-2 text-xs font-bold text-primary"><Sparkles size={14}/> Explanation generated</div><p className="mt-5 text-sm leading-7">{explain.data?.explanation??`${priorityRoute?.routeId??'The priority route'} is the pressure point because its live demand signal rises above the capacity envelope. The next allocation should address that corridor first while the remaining routes stay within their observed operating range.`}</p><div className="mt-6 border-t border-primary/20 pt-4 font-mono-ui text-[10px] text-muted-foreground">based on configured evidence · not a new model output</div></>:<div className="flex h-full min-h-[240px] flex-col items-center justify-center text-center"><div className="grid h-12 w-12 place-items-center rounded-xl border border-border bg-card text-muted-foreground"><Sparkles size={19}/></div><div className="mt-4 font-display font-bold">No narration has been requested</div><p className="mt-1 max-w-xs text-xs leading-5 text-muted-foreground">Use the button above to turn the current evidence into a concise review note.</p></div>}</div></Panel></div></>; }

export function SettingsPage(){ return <><PageIntro eyebrow="Settings / system" title="Keep the assumptions close." description="MetroMind is built to be questioned. This workspace makes its role, provenance, and academic shortcuts visible."/><div className="grid gap-5 xl:grid-cols-2"><Panel title="Workspace identity" meta="access context"><div className="space-y-5"><div className="flex items-center gap-4"><div className="grid h-12 w-12 place-items-center rounded-xl bg-primary text-primary-foreground font-display font-bold">AM</div><div><div className="font-display font-bold">Alex Morgan</div><div className="mt-1 text-xs text-muted-foreground">Transport planning · reviewer role</div></div></div><div className="grid grid-cols-2 gap-4 border-t border-border/70 pt-5"><div><div className="font-mono-ui text-[9px] uppercase text-muted-foreground">Role</div><div className="mt-1 text-sm font-bold">Operator / reviewer</div></div><div><div className="font-mono-ui text-[9px] uppercase text-muted-foreground">Workspace</div><div className="mt-1 text-sm font-bold">Northstar Transit Lab</div></div></div></div></Panel><Panel title="System information" meta="runtime"><div className="space-y-4">{[['API contract','v0.1.0'],['Model pipeline','Gradient Boosting'],['Data source','demo_2024_q2.csv'],['Last refresh','Today · 09:41:22'],['Health endpoint','/api/healthz']].map(([l,v])=><div key={l} className="flex items-center justify-between border-b border-border/60 pb-3 text-xs last:border-0"><span className="text-muted-foreground">{l}</span><span className="font-mono-ui">{v}</span></div>)}</div></Panel><Panel title="Academic assumptions" meta="read before viva"><div className="space-y-3 text-xs leading-5 text-muted-foreground"><p><strong className="text-foreground">Uncertainty:</strong> intervals represent residual uncertainty around a point estimate; they are not calibrated guarantees.</p><p><strong className="text-foreground">Causality:</strong> association features support prediction, not causal inference.</p><p><strong className="text-foreground">Optimization:</strong> buses are treated as interchangeable and route travel time is not modeled in the objective.</p></div></Panel><Panel title="Demo data note" meta="reproducible"><div className="flex gap-3"><FlaskConical size={17} className="mt-0.5 shrink-0 text-primary"/><p className="text-xs leading-5 text-muted-foreground">The included dataset is synthetic and deterministic so every analysis can be reproduced during a college mathematics viva. Replace it with an AVL export before operational use.</p></div></Panel></div></>; }

export function PassengerPage() {
  const routesQuery = useGetRoutes();
  const predict = usePredictDemand();
  const routes = routesQuery.data ?? demoRoutes;
  const [routeId, setRouteId] = useState(routes[0]?.routeId ?? 'M1');
  const [date, setDate] = useState('2024-06-27');
  const [hour, setHour] = useState('18');
  const [prediction, setPrediction] = useState<PredictionResult | null>(null);
  const selectedRoute = routes.find((route) => route.routeId === routeId) ?? routes[0];
  const selectedPrediction = prediction?.routes.find((route) => route.routeId === selectedRoute?.routeId);
  const run = () => predict.mutate({
    data: {
      date,
      hour: Number(hour),
      rainfall: 0,
      temperature: 18,
      isHoliday: false,
      specialEvent: false,
      demandMultiplier: 1,
    },
  }, { onSuccess: setPrediction });
  const expectedDemand = selectedPrediction?.predictedDemand ?? 0;
  const utilization = selectedRoute?.capacity ? expectedDemand / selectedRoute.capacity : 0;
  const crowding = utilization >= 1 ? 'High' : utilization >= .85 ? 'Moderate' : 'Low';
  const suggestion = crowding === 'High'
    ? 'Try leaving 30–45 minutes earlier or later; the adjacent service window has more spare capacity.'
    : crowding === 'Moderate'
      ? 'If your schedule allows, travel outside the peak window for a more comfortable boarding experience.'
      : 'This window is comparatively quiet. It is a good choice when you want a less-crowded journey.';
  return <><PageIntro eyebrow="Passenger / public view" title="Plan around the crowd, not just the clock." description="Choose a route and departure window. MetroMind returns the expected load and keeps the uncertainty-aware operator signal easy to read." action={<Button onClick={run} disabled={predict.isPending} testId="button-passenger-predict">{predict.isPending ? <LoaderCircle size={14} className="animate-spin"/> : <Waypoints size={14}/>} Check crowding</Button>}/>{routesQuery.isError&&<div className="mb-5"><ErrorNote retry={()=>routesQuery.refetch()}/></div>}<div className="grid gap-5 xl:grid-cols-[320px_1fr]"><Panel title="Your journey" meta="route and departure"><div className="space-y-5"><label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">route</span><select value={routeId} onChange={e=>{setRouteId(e.target.value);setPrediction(null)}} data-testid="select-passenger-route" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm font-semibold outline-none">{routes.map(route=><option key={route.routeId} value={route.routeId}>{route.routeId} · {route.name}</option>)}</select></label><label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">date</span><input type="date" value={date} onChange={e=>setDate(e.target.value)} data-testid="input-passenger-date" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm font-semibold outline-none"/></label><label className="block"><span className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">departure time</span><input type="time" value={`${hour.padStart(2,'0')}:00`} onChange={e=>setHour(e.target.value.split(':')[0])} data-testid="input-passenger-time" className="mt-2 w-full rounded-lg border border-input bg-background px-3 py-2.5 text-sm font-semibold outline-none"/></label><div className="rounded-xl border border-primary/25 bg-primary/[.05] p-4 text-[11px] leading-5 text-muted-foreground"><Info size={14} className="mb-2 text-primary"/>The passenger view uses the active model with neutral weather and standard service-day conditions.</div></div></Panel><div className="space-y-5">{predict.isError&&<ErrorNote/>}{selectedPrediction ? <><Panel title={`${selectedRoute?.routeId ?? 'Route'} at ${hour.padStart(2,'0')}:00`} meta={prediction?.model ?? 'active model'}><div className="grid gap-4 sm:grid-cols-3"><div className="rounded-xl bg-sidebar p-5 text-sidebar-foreground"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-sidebar-foreground/45">expected demand</div><div className="mt-3 font-display text-4xl font-bold text-sidebar-primary">{Math.round(expectedDemand).toLocaleString()}</div><div className="mt-1 text-[11px] text-sidebar-foreground/55">passenger boardings</div></div><div className="rounded-xl border border-border p-5"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">crowding level</div><div className={`mt-3 font-display text-3xl font-bold ${crowding==='High'?'text-accent':crowding==='Moderate'?'text-chart-4':'text-primary'}`}>{crowding}</div><div className="mt-1 text-[11px] text-muted-foreground">capacity signal</div></div><div className="rounded-xl border border-border p-5"><div className="font-mono-ui text-[9px] uppercase tracking-wider text-muted-foreground">utilization</div><div className="mt-3 font-display text-3xl font-bold">{Math.round(utilization*100)}%</div><div className="mt-3 h-1.5 rounded-full bg-muted"><div className={`h-full rounded-full ${crowding==='High'?'bg-accent':'bg-primary'}`} style={{width:`${Math.min(utilization*100,100)}%`}}/></div></div></div><div className="mt-5 flex gap-4 rounded-xl border border-primary/25 bg-primary/[.05] p-5"><Waypoints size={18} className="mt-0.5 shrink-0 text-primary"/><div><div className="font-display font-bold">A less-crowded suggestion</div><p className="mt-1 text-xs leading-5 text-muted-foreground">{suggestion}</p></div></div></Panel><Panel title="Forecast interval" meta="show your uncertainty"><div className="flex items-center justify-between text-xs"><span>likely demand band</span><span className="font-mono-ui text-muted-foreground">{Math.round(selectedPrediction.lowerBound).toLocaleString()} — {Math.round(selectedPrediction.upperBound).toLocaleString()} passengers</span></div><div className="relative mt-4 h-3 rounded-full bg-muted"><div className="absolute h-3 rounded-full bg-primary/25" style={{left:`${Math.max(0,selectedPrediction.lowerBound/selectedPrediction.upperBound*70)}%`,right:'7%'}}/><div className="absolute top-[-3px] h-5 w-1 rounded-full bg-primary" style={{left:`${Math.min(94,selectedPrediction.predictedDemand/selectedPrediction.upperBound*86)}%`}}/></div><p className="mt-4 text-[11px] leading-5 text-muted-foreground">The band is a planning interval, not a promise. It is shown so a comfortable-looking point estimate does not hide the tail.</p></Panel></> : <EmptyNotice text="Set a route and departure window, then check crowding to see the passenger forecast."/>}</div></div></>;
}